// Launch Params: the launch row is the contract. Client (resolves the base), View (a Companies view
// by name, required), Tag (log only), and the five fields this Rootflow owns on Automations: Prompt
// (what DiscoGen is asked), Output Field (the column it writes), Output Type (how that column is
// created), Web Search, Evidence, Overwrite; plus Max companies as the spend cap (DiscoGen runs on
// the account's own LLM key). Table is implied (Companies); a filled Table that is not Companies is
// refused, the Operator meant another machine.
//
// REFUSALS: a badly filled row is an expected outcome, not a crash. Every guard returns a refusal
// item (`refused` carries the reason); Launch OK? routes it to Build Refusal, which closes the row
// Failed with the reason. Nothing is read, submitted or paid for before the guards pass.
const rec=$('Fetch Launch Record').first().json||{};
const f=rec.fields||{};
const cf=(($('Resolve Base').first().json||{}).fields)||{};
const base=String(cf['Clayroots Base ID']||'').trim();
const arr=(v)=>Array.isArray(v)?v:(v==null||v===''?[]:[v]);
const clientRecId=(arr(f['Client']).map(x=>(x&&typeof x==='object')?x.id:x)[0])||'';
const table=String(f['Table']||'').trim();
const view=String(f['View']||'').trim();
const tag=String(f['Tag']||'').trim();
const prompt=String(f['Prompt']||'').trim();
const outputField=String(f['Output Field']||'').trim();
const outputType=String(f['Output Type']||'Long text').trim();
const TYPES=['Long text','Text','Number','Checkbox','Single select'];
const maxRaw=f['Max companies'];
const maxCompanies=(maxRaw===undefined||maxRaw===null||maxRaw==='')?0:Number(maxRaw);
const startedAt=new Date().toISOString();
const where='Launch record '+(rec.id||'?');
const p={ refused:'', base, clientRecId, table:'Companies', view, tag, prompt, outputField, outputType, webSearch:!!f['Web Search'], evidence:!!f['Evidence'], overwrite:!!f['Overwrite'], maxCompanies, trigger:'form', _launchRecordId:rec.id||'', startedAt };
const refuse=(r)=>[{ json:Object.assign({},p,{ refused:r, table:table||'Companies' }) }];
if(!clientRecId) return refuse(where+' has no Client link. Nothing was asked.');
if(!/^app[A-Za-z0-9]{14}$/.test(base)) return refuse('Client on '+where.toLowerCase()+' has no valid Clayroots Base ID. Nothing was asked.');
if(table&&table.toLowerCase()!=='companies') return refuse(where+' names Table "'+table+'". DiscoGen answers per domain, so this machine runs on Companies only. Nothing was asked.');
if(!view) return refuse(where+' has no View. A Companies view is required by name. Nothing was asked.');
if(!prompt) return refuse(where+' has no Prompt. Nothing was asked.');
if(!outputField) return refuse(where+' has no Output Field. Name the column the answer goes into. Nothing was asked.');
if(/\s(Evidence|Confidence)$/.test(outputField)) return refuse(where+' names Output Field "'+outputField+'", which ends in Evidence or Confidence: those suffixes are reserved for the companion columns. Nothing was asked.');
if(TYPES.indexOf(outputType)<0) return refuse(where+' names Output Type "'+outputType+'". Accepted: '+TYPES.join(', ')+'. Nothing was asked.');
if(!(maxCompanies>0)) return refuse(where+' has no Max companies. DiscoGen spends the account\'s LLM key per company; set the cap. Nothing was asked.');
return [{ json:p }];

// Event Params: the record door. Any caller may POST {baseId, clientRecordId, view, prompt,
// outputField, outputType, webSearch, evidence, overwrite, maxCompanies, tag}; the same contract as
// the launch row, the same refusals, no launch row and no Running stamp (the close creates the run
// row on Execution ID). The door answers 200 on receipt and the run carries on alone.
const b=($input.first().json||{}).body||{};
const s=(v)=>String(v==null?'':v).trim();
const base=s(b.baseId||b.base);
const table=s(b.table)||'Companies';
const view=s(b.view);
const prompt=s(b.prompt);
const outputField=s(b.outputField||b.output_field);
const outputType=s(b.outputType||b.output_type)||'Long text';
const TYPES=['Long text','Text','Number','Checkbox','Single select'];
const maxCompanies=Number(b.maxCompanies||b.max_companies)||0;
const startedAt=new Date().toISOString();
const p={ refused:'', base, clientRecId:s(b.clientRecordId||b.clientRecId), table:'Companies', view, tag:s(b.tag), prompt, outputField, outputType, webSearch:!!(b.webSearch||b.web_search), evidence:!!b.evidence, overwrite:!!b.overwrite, maxCompanies, trigger:'event', _launchRecordId:'', startedAt };
const refuse=(r)=>[{ json:Object.assign({},p,{ refused:r, table }) }];
if(!/^app[A-Za-z0-9]{14}$/.test(base)) return refuse('Record door: no valid baseId in the body. Nothing was asked.');
if(table.toLowerCase()!=='companies') return refuse('Record door: Table "'+table+'" is not Companies. Nothing was asked.');
if(!view) return refuse('Record door: no view in the body. Nothing was asked.');
if(!prompt) return refuse('Record door: no prompt in the body. Nothing was asked.');
if(!outputField) return refuse('Record door: no outputField in the body. Nothing was asked.');
if(/\s(Evidence|Confidence)$/.test(outputField)) return refuse('Record door: outputField "'+outputField+'" ends in a reserved suffix. Nothing was asked.');
if(TYPES.indexOf(outputType)<0) return refuse('Record door: outputType "'+outputType+'" is not one of '+TYPES.join(', ')+'. Nothing was asked.');
if(!(maxCompanies>0)) return refuse('Record door: no maxCompanies in the body; the spend cap is required. Nothing was asked.');
return [{ json:p }];

// Params: one shape for both entries. Whichever entry ran wrote its item; this re-emits it so every
// node after reads $('Params') and never cares which door opened the run.
let p=null;
try{ p=$('Launch Params').first().json; }catch(e){}
if(!p||(!p.base&&!p.refused)){ try{ p=$('Event Params').first().json; }catch(e){} }
if(!p) throw new Error('Enrich Discogen Research: no entry produced launch parameters.');
return [{ json:p }];

// Resolve Table: Companies by name in the base meta just read, the view by name or id. A base
// without Companies or without the view is refused on the row (Table OK? routes to Build Refusal).
// Field names and types travel for the column check. Nothing here creates.
const p=$('Params').first().json;
const r=$input.first().json||{}; const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
const refuse=(why)=>[{ json:{ refused:why } }];
if(!tables) return refuse('Could not read the table list for base '+p.base+': '+JSON.stringify(body).slice(0,200)+'. Nothing was asked.');
const t=tables.find(x=>String(x.name||'').trim().toLowerCase()==='companies');
if(!t) return refuse('Base '+p.base+' has no Companies table. Nothing was asked.');
const v=(t.views||[]).find(x=>x.id===p.view||String(x.name||'').trim()===p.view);
if(!v) return refuse('Companies ('+t.id+') in base '+p.base+' has no view "'+p.view+'". Nothing was asked.');
const types={}; for(const f of (t.fields||[])) types[f.name]=f.type;
return [{ json:{ refused:'', tableId:t.id, tableName:t.name, viewId:v.id, viewName:v.name, fieldNames:(t.fields||[]).map(f=>f.name), fieldTypes:types } }];

// Check Columns: the requirement (Domain, written by the Inserts) and the fields this run owns:
// Output Field at the Airtable type Output Type declares, and with Evidence on the two companions
// '<Output Field> Evidence' (long text) and '<Output Field> Confidence' (number). Created on first
// use when the table lacks them. A column that exists at another type belongs to someone else and
// the run is refused on the row (it never retypes, never renames). Also emits the field list the
// row read asks for, so a 10,000-row view does not carry every column.
const p=$('Params').first().json;
const t=$('Resolve Table').first().json;
const have=t.fieldTypes||{};
const refuse=(why)=>[{ json:{ refused:why } }];
if(!('Domain' in have)) return refuse('Companies ('+t.tableId+') in base '+p.base+' has no Domain column. An Insert Rootflow owes it. Nothing was asked.');
const AT={ 'Long text':{ type:'multilineText' }, 'Text':{ type:'singleLineText' }, 'Number':{ type:'number', options:{ precision:2 } }, 'Checkbox':{ type:'checkbox', options:{ icon:'check', color:'greenBright' } }, 'Single select':{ type:'singleSelect', options:{ choices:[] } } };
const own=[ Object.assign({ name:p.outputField }, AT[p.outputType]) ];
if(p.evidence){ own.push({ name:p.outputField+' Evidence', type:'multilineText' }); own.push({ name:p.outputField+' Confidence', type:'number', options:{ precision:2 } }); }
const clash=own.filter(f=>(f.name in have)&&have[f.name]!==f.type);
if(clash.length) return refuse('Companies ('+t.tableId+') already holds '+clash.map(f=>'"'+f.name+'" as '+have[f.name]+' (this run wants '+f.type+')').join(', ')+'. A column at another type is not this run\'s to write; pick another Output Field or Output Type. Nothing was asked.');
const toCreate=own.filter(f=>!(f.name in have));
const url='https://api.airtable.com/v0/meta/bases/'+p.base+'/tables/'+t.tableId+'/fields';
return [{ json:{ refused:'', base:p.base, tableId:t.tableId, own:own.map(f=>f.name), toCreate:toCreate.map(f=>f.name), creates:toCreate.map(f=>({ url, body:f })), fetchFields:['Domain'].concat(own.map(f=>f.name)) } }];

// Plan Columns: one meta-API call per own field the table lacks. Runs only when there is something
// to create; the IF before it routes an empty plan straight to the row read.
const c=$('Check Columns').first().json;
return (c.creates||[]).map(x=>({ json:x }));

// Verify Columns: the base meta read again after the creates. Every own field must now show;
// anything still missing stops the run by name before a row is read (a crash here is a real
// defect: the meta API accepted a create it did not perform).
const c=$('Check Columns').first().json;
const r=$input.first().json||{}; const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
if(!tables) throw new Error('Could not re-read the table list for base '+c.base+' after creating columns: '+JSON.stringify(body).slice(0,200)+'.');
const names=new Set((((tables.find(t=>t.id===c.tableId))||{}).fields||[]).map(f=>f.name));
const still=(c.toCreate||[]).filter(n=>!names.has(n));
if(still.length){ let why=''; try{ why=$('Create Columns').all().map(i=>JSON.stringify(i.json).slice(0,200)).join(' | '); }catch(e){} throw new Error('Enrich Discogen Research created columns the base does not show: '+still.join(', ')+'. Airtable answered: '+why); }
return [{ json:{ created:c.toCreate.slice() } }];

// Pick Rows: the view's rows become the ask. A row without a Domain is skipped and counted; a row
// already holding a value in Output Field is skipped unless Overwrite; several rows on one domain
// share one ask and all receive the answer. The spend gate: more domains to ask than Max companies
// is a refusal on the row (DiscoGen bills the account's LLM key per domain), never a silent cut.
// One item out: the plan, or a refusal, or {_none} when nothing is left to ask.
const p=$('Params').first().json;
const c=$('Check Columns').first().json;
const norm=(d)=>String(d||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'');
const held=(v)=>!(v===undefined||v===null||v===''||v===false||(Array.isArray(v)&&!v.length));
const rows=$input.all().map(i=>i.json||{}).filter(j=>j.id);
const st={ inView:rows.length, noDomain:0, alreadyAnswered:0, asked:0, domains:0 };
const byDomain={};
for(const r of rows){
  const f=r.fields||{};
  const d=norm(f.Domain); if(!d){ st.noDomain++; continue; }
  if(!p.overwrite&&held(f[p.outputField])){ st.alreadyAnswered++; continue; }
  st.asked++;
  (byDomain[d]=byDomain[d]||[]).push(String(r.id));
}
const domains=Object.keys(byDomain);
st.domains=domains.length;
if(!domains.length) return [{ json:{ _none:true, refused:'', stats:st } }];
if(domains.length>p.maxCompanies) return [{ json:{ refused:'View "'+p.view+'" has '+domains.length+' companies to ask and Max companies is '+p.maxCompanies+'. Raise the cap or narrow the view. Nothing was asked.', stats:st } }];
return [{ json:{ refused:'', stats:st, byDomain, domains } }];

// Make Tasks: one DiscoGen submit per 10,000 domains (the endpoint's ceiling), never split smaller
// and never in parallel: every task runs on the same LLM key and parallel tasks rate-limit each
// other (the discolike skill's law). The Prompt goes as written; with Evidence on, the two extra
// asks are appended as numbered questions, the one shape DiscoGen honors: it infers a JSON schema
// from the numbered questions and answers each domain with an object (proven 2026-09-12, run 24520;
// a "return JSON with these keys" instruction is ignored, run 24517, DiscoGen normalizes the answer
// to a bare value). Results maps the object back onto the three columns by its field labels.
// context_mode website: company profile plus homepage text, the richest context DiscoGen offers.
const p=$('Params').first().json;
const plan=$input.first().json||{};
if(plan._none||plan.refused) return [{ json:{ _none:true } }];
const SHAPE=' If the source does not say, answer unknown. 2. Quote one short verbatim sentence from the source that supports the answer, or write none. 3. Your confidence in the answer as a number from 0 to 1.';
const query=p.evidence?('1. '+p.prompt.replace(/^\s*1\.\s*/,'')+SHAPE):p.prompt;
const out=[];
const domains=plan.domains||[];
for(let i=0;i<domains.length;i+=10000){
  const part=domains.slice(i,i+10000);
  out.push({ json:{ idx:out.length, count:part.length, body:{ query, domains:part, context_mode:'website', web_search:!!p.webSearch } } });
}
return out;

// Init Tasks: the submit answers (aligned to Make Tasks by index) become the poll carriers: one item
// per task with its task_id, or a submit error named on the item. A missing credential, a 400 (no
// LLM provider on the account, no search provider with Web Search on), a 402 or a dead API are all
// errors on the task, never a crash: the run reports them on the row and moves on.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const reqs=$('Make Tasks').all().map(i=>i.json||{}).filter(j=>!j._none);
const t0=Date.now();
const out=$input.all().map((it,i)=>{
  const q=reqs[i]||{}; const j=it.json||{};
  if(j.error&&j.body===undefined&&j.task_id===undefined){ const m=errMsg(j.error); return { json:{ idx:q.idx, count:q.count, taskId:'', status:'', progress:0, results:null, cost:0, submitErr:(/credential/i.test(m)?'no credential on the DiscoGen nodes':m).slice(0,200), _t0:t0 } }; }
  const b=(j.body!==undefined)?j.body:j; const code=Number(j.statusCode)||200;
  const parsed=(typeof b==='string')?(()=>{ try{ return JSON.parse(b); }catch(e){ return {}; } })():(b||{});
  if(code>=300||!parsed.task_id){ const why=(parsed&&(parsed.detail||parsed.message||parsed.error))||JSON.stringify(parsed).slice(0,160); return { json:{ idx:q.idx, count:q.count, taskId:'', status:'', progress:0, results:null, cost:0, submitErr:('HTTP '+code+' '+(typeof why==='string'?why:JSON.stringify(why))).slice(0,200), _t0:t0 } }; }
  return { json:{ idx:q.idx, count:q.count, taskId:String(parsed.task_id), status:String(parsed.status||'in_progress'), progress:0, results:null, cost:0, submitErr:'', _t0:t0 } };
});
if(!out.length) return [{ json:{ _none:true } }];
return out;

// Poll Input: the carriers of every open task, re-emitted each round so DG Poll asks once per task
// and Poll Gate folds by index. First round from Init Tasks, later rounds from the Wait.
const items=$input.all().map(i=>i.json||{}).filter(j=>!j._none);
if(!items.length) return [{ json:{ _none:true } }];
return items.map(j=>({ json:j }));

// Poll Gate: the status answers (one per carrier, aligned by index; every open task is polled every
// round, the proven poller shape) folded onto the carriers. A task is settled when DiscoGen says
// completed, failed or cancelled; its results map (domain -> answer) and estimated cost ride on the
// carrier. Loop while any task is open and the 8-hour cap has not passed; the wait grows 30, 60,
// 120, 300 s. A task still open at the cap is reported as timed out with its id, so it can be read
// by hand: DiscoGen keeps the task.
const MAX=8*3600*1000;
const carriers=$('Poll Input').all().map(i=>i.json||{});
const polls=$input.all().map(i=>i.json||{});
const t0=Number((carriers[0]||{})._t0)||Date.now();
const elapsed=Date.now()-t0;
const DONE=['completed','failed','cancelled','canceled','error'];
const out=carriers.map((c,idx)=>{
  if(!c.taskId||DONE.indexOf(c.status)>-1) return c;
  const j=polls[idx]||{}; const b=(j.body!==undefined)?j.body:j;
  const parsed=(typeof b==='string')?(()=>{ try{ return JSON.parse(b); }catch(e){ return {}; } })():(b||{});
  if(j.error&&j.body===undefined&&parsed.status===undefined) return Object.assign({},c,{ pollErr:String((j.error&&j.error.message)||j.error||'poll failed').slice(0,160) });
  const status=String(parsed.status||c.status||'in_progress');
  const results=(status==='completed'&&parsed.results&&typeof parsed.results==='object')?parsed.results:(c.results||null);
  return Object.assign({},c,{ status, progress:Number(parsed.progress)||c.progress||0, results, format:parsed.response_format||c.format||null, cost:Number(parsed.estimated_cost)||c.cost||0, pollErr:'', failReason:(status==='failed'||status==='error')?String(parsed.error||parsed.message||parsed.detail||'task failed').slice(0,200):(c.failReason||'') });
});
const anyOpen=out.some(c=>c.taskId&&DONE.indexOf(c.status)<0);
const loop=anyOpen&&elapsed<MAX;
const w=elapsed<120000?30:elapsed<600000?60:elapsed<1800000?120:300;
return out.map(c=>({ json:Object.assign({},c,{ _loop:loop, _nextWaitSec:w, _elapsedS:Math.round(elapsed/1000), timedOut:(c.taskId&&DONE.indexOf(c.status)<0&&!loop) }) }));

// Results: every settled task's results map (domain -> answer) becomes one write row per Companies
// row of that domain. DiscoGen answers either a bare value (a one-question prompt) or an object whose
// keys it named itself from the questions (a numbered prompt); the task's response_format carries the
// labels (proven 2026-09-12, run 24520: {market_type, supporting_quote, confidence}).
// Evidence off: a bare value is written verbatim into Output Field, coerced to the column's type
// (Number: the first number in the text; Checkbox: yes/true; Single select: the text, typecast mints
// the choice); an object is written as "Label: value" lines. Evidence on: the object is mapped onto
// the three columns: the confidence key (/confid/), the quote key (/quote|evidence|source/), and the
// first remaining key is the answer; "unknown" is written blank in Output Field with the quote and
// confidence beside it, so a rerun picks it up; a bare value with no object is the answer with no
// evidence and is counted unparsed. A domain DiscoGen did not answer is counted missing.
const p=$('Params').first().json;
const plan=$('Pick Rows').first().json||{};
const byDomain=plan.byDomain||{};
let tasks=[]; try{ tasks=$input.all().map(i=>i.json||{}).filter(j=>!j._none); }catch(e){}
const st={ tasks:tasks.length, submitted:0, submitErrors:[], failedTasks:[], timedOut:[], answered:0, unknown:0, unparsed:0, missing:0, rows:0, cost:0, taskIds:[] };
const results={}; const labelsOf={};
for(const t of tasks){
  if(t.taskId) st.taskIds.push(t.taskId);
  if(t.submitErr){ st.submitErrors.push('task '+t.idx+' ('+t.count+' domains): '+t.submitErr); continue; }
  st.submitted+=Number(t.count)||0; st.cost+=Number(t.cost)||0;
  if(t.timedOut){ st.timedOut.push(t.taskId+' ('+t.count+' domains, '+(t.progress||0)+'%)'); continue; }
  if(t.status!=='completed'){ st.failedTasks.push(t.taskId+': '+(t.failReason||t.status)); continue; }
  const labels=((t.format||{}).field_labels)||{};
  for(const k of Object.keys(t.results||{})){ const d=String(k).toLowerCase(); results[d]=t.results[k]; labelsOf[d]=labels; }
}
const strip=(s)=>String(s).replace(/^\s*```(?:json)?\s*/i,'').replace(/\s*```\s*$/,'').trim();
const asObject=(v)=>{ if(v&&typeof v==='object'&&!Array.isArray(v)) return v; if(typeof v!=='string') return null; const s=strip(v); if(!/^\{[\s\S]*\}$/.test(s)) return null; try{ const o=JSON.parse(s); return (o&&typeof o==='object'&&!Array.isArray(o))?o:null; }catch(e){ return null; } };
const text=(v)=>{ if(v===undefined||v===null) return ''; if(typeof v==='object') return JSON.stringify(v); return String(v).trim(); };
const coerce=(v)=>{ const s=text(v); if(!s) return undefined; if(p.outputType==='Number'){ const m=s.replace(/,/g,'').match(/-?\d+(\.\d+)?/); return m?Number(m[0]):undefined; } if(p.outputType==='Checkbox'){ if(/^(yes|true|y)\b/i.test(s)) return true; if(/^(no|false|n)\b/i.test(s)) return false; return undefined; } return s; };
const pickKeys=(o)=>{ const keys=Object.keys(o); const conf=keys.find(k=>/confid/i.test(k))||''; const ev=keys.find(k=>k!==conf&&/quote|evidence|source|support/i.test(k))||''; const ans=keys.find(k=>k!==conf&&k!==ev)||''; return { ans, ev, conf }; };
const lines=(o,labels)=>Object.keys(o).map(k=>(labels[k]||k)+': '+text(o[k])).join('\n');
const out=[];
for(const d of Object.keys(byDomain)){
  if(!(d in results)){ st.missing++; continue; }
  const raw=results[d]; const o=asObject(raw);
  const fields={};
  if(p.evidence){
    if(!o){ st.unparsed++; const c=coerce(raw); if(c!==undefined) fields[p.outputField]=c; fields[p.outputField+' Evidence']=''; }
    else {
      const k=pickKeys(o);
      const ans=text(o[k.ans]);
      const ev=text(o[k.ev]); const evClean=/^(none|n\/a|null|)$/i.test(ev)?'':ev;
      const unknown=!ans||/^unknown$/i.test(ans);
      if(unknown){ st.unknown++; fields[p.outputField+' Evidence']=evClean||'unknown: the source does not say'; }
      else { st.answered++; const c=coerce(ans); if(c!==undefined) fields[p.outputField]=c; fields[p.outputField+' Evidence']=evClean; }
      const conf=Number(String(o[k.conf]||'').replace(/[^0-9.]/g,'')); if(isFinite(conf)&&k.conf) fields[p.outputField+' Confidence']=Math.max(0,Math.min(1,conf));
    }
  } else {
    const v=o?lines(o,labelsOf[d]||{}):raw;
    const c=coerce(v);
    if(c===undefined){ st.unknown++; continue; }
    st.answered++; fields[p.outputField]=c;
  }
  if(p.overwrite&&fields[p.outputField]===undefined&&p.outputType!=='Checkbox') fields[p.outputField]=p.outputType==='Number'?null:'';
  for(const id of byDomain[d]){ st.rows++; out.push({ json:Object.assign({ id }, fields) }); }
}
if(!out.length) return [{ json:{ _empty:true, _stats:st } }];
out[0].json._stats=st;
return out;

// Chunk Rows: the write rows in tens, one item per Airtable request, PATCHed as {records:[{id,
// fields}], typecast:true} 200 ms apart (typecast lets a Single select mint its choices). Ids and
// size ride on the item for the count-back; carriers are stripped.
const rows=$input.all().map(i=>i.json).filter(j=>j&&j.id&&!j._empty);
const out=[];
for(let i=0;i<rows.length;i+=10){
  const part=rows.slice(i,i+10);
  out.push({ json:{ body:{ records:part.map(r=>{ const f={}; for(const k of Object.keys(r)){ if(k!=='id'&&k.charAt(0)!=='_') f[k]=r[k]; } return { id:String(r.id), fields:f }; }), typecast:true }, ids:part.map(r=>String(r.id)), size:part.length } });
}
if(!out.length) return [{ json:{ _none:true, size:0, ids:[] } }];
return out;

// Write Check: the writer's count-back. Written rows are counted from every 2xx answer's records[];
// a request that was not 2xx counts every row it carried as a write error and names the ids. Exactly
// one item out.
const n=(v)=>Number(v)||0;
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
let chunks=[], resps=[];
try{ chunks=$('Chunk Rows').all().map(i=>i.json).filter(j=>!j._none); }catch(e){}
try{ resps=$('Write Rows').all(); }catch(e){}
let written=0, writeErrors=0; const failed=[], reasons=[];
const note=(ids,why)=>{ for(const id of (ids||[])){ if(failed.length<200) failed.push(id); } const w=String(why||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,180); if(w&&reasons.length<10) reasons.push(w); };
resps.forEach((it,i)=>{
  const c=chunks[i]||{ size:0, ids:[] }; const j=it.json||{};
  if(!c.size) return;
  if(j.error&&j.statusCode===undefined){ writeErrors+=n(c.size); note(c.ids,'row writer: '+String((j.error&&j.error.message)||j.error||'call failed')); return; }
  const status=n(j.statusCode); const b=parse(j.body===undefined?null:j.body);
  if(status>=200&&status<300&&b&&Array.isArray(b.records)){ written+=b.records.length; if(b.records.length<n(c.size)){ const back={}; for(const r of b.records) back[String((r||{}).id||'')]=1; writeErrors+=n(c.size)-b.records.length; note((c.ids||[]).filter(id=>!back[id]),(n(c.size)-b.records.length)+' of '+c.size+' records missing from a 2xx answer'); } return; }
  const e=b&&b.error; const why=e?(typeof e==='object'?(e.message||e.type||JSON.stringify(e)):String(e)):((j.error&&j.error.message)||(typeof j.body==='string'?j.body:''));
  writeErrors+=n(c.size); note(c.ids,'HTTP '+status+' '+String(why||'')+(status===429?' (rate limited; never retried)':''));
});
return [{ json:{ written, writeErrors, writeRequests:resps.length, failed, writeReasons:reasons } }];

// Build Log: the run's one row. Reads the pick, the tasks and the writer's count-back, and writes
// the verdict on Execution ID (the launch row when the Hub fired it, a new row on an event call).
// Status is computed: submit errors, failed or timed-out tasks and refused writes are errors;
// no-domain rows, already-answered rows, unknown answers and unanswered domains are skips.
const p=$('Params').first().json;
let t={}; try{ t=$('Resolve Table').first().json||{}; }catch(e){}
let c={}; try{ c=$('Check Columns').first().json||{}; }catch(e){}
let pick={}; try{ pick=$('Pick Rows').first().json||{}; }catch(e){}
const ps=pick.stats||{ inView:0, noDomain:0, alreadyAnswered:0, asked:0, domains:0 };
let rs=null; try{ const first=$('Results').first().json||{}; rs=first._stats||null; }catch(e){}
rs=rs||{ tasks:0, submitted:0, submitErrors:[], failedTasks:[], timedOut:[], answered:0, unknown:0, unparsed:0, missing:0, rows:0, cost:0, taskIds:[] };
let w={ written:0, writeErrors:0, writeRequests:0, failed:[], writeReasons:[] }; try{ w=Object.assign(w,$('Write Check').first().json||{}); }catch(e){}
const n=(v)=>Number(v)||0;
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const failedCount=rs.submitErrors.length+rs.failedTasks.length+rs.timedOut.length+n(w.writeErrors);
const created=(c.toCreate||[]);
const lines=[
  '**'+n(rs.answered)+' of '+n(ps.domains)+' companies answered into "'+p.outputField+'"'+(p.evidence?' (with evidence and confidence)':'')+', '+n(w.written)+' rows written'+(failedCount?', '+failedCount+' errors':'')+'**',
  '',
  '**Scope:** one client, Companies view "'+(t.viewName||p.view)+'"'+(p.tag?', Tag "'+p.tag+'"':'')+', '+n(ps.inView)+' rows in the view, '+n(ps.domains)+' distinct domains asked across '+n(rs.tasks)+' DiscoGen task'+(rs.tasks===1?'':'s')+', cap '+n(p.maxCompanies),
  '**Prompt:** '+String(p.prompt||'').replace(/\s+/g,' ').slice(0,400)+(String(p.prompt||'').length>400?'...':''),
  '**Settings:** Output Type '+p.outputType+', Web Search '+(p.webSearch?'on':'off')+', Evidence '+(p.evidence?'on':'off')+', Overwrite '+(p.overwrite?'on':'off')+', context website, the account\'s default LLM'+(p.webSearch?' and search provider':''),
  '',
  '**Results**',
  '- **Answered:** '+n(rs.answered)+'; **unknown (written blank):** '+n(rs.unknown)+(p.evidence?'; **unparsed (written verbatim):** '+n(rs.unparsed):'')+'; **not answered by DiscoGen:** '+n(rs.missing),
  '- **Rows written (confirmed by Airtable):** '+n(w.written)+(n(w.writeErrors)?', '+n(w.writeErrors)+' refused':''),
  '- **Columns created on first use:** '+(created.length?created.join(', '):'none (already there)'),
  '- **DiscoGen estimated cost (their figure, LLM fees on the account key):** $'+n(rs.cost).toFixed(4),
  '- **Task ids:** '+(rs.taskIds.length?rs.taskIds.join(', '):'none')
];
const skips=[];
if(n(ps.noDomain)) skips.push(n(ps.noDomain)+' rows with no Domain');
if(n(ps.alreadyAnswered)) skips.push(n(ps.alreadyAnswered)+' rows already holding a value (Overwrite off)');
if(!n(ps.inView)) skips.push('the view had no rows');
if(n(ps.inView)&&!n(ps.domains)) skips.push('nothing left to ask');
if(skips.length) lines.push('', '**Skipped ('+skips.join('; ')+')**');
const fails=[].concat(rs.submitErrors.map(x=>'submit: '+x), rs.failedTasks.map(x=>'task failed: '+x), rs.timedOut.map(x=>'task still running at the 8-hour cap, read it by hand: '+x), (w.writeReasons||[]).map(x=>'write: '+x));
if(fails.length){ lines.push('', '**Failures ('+failedCount+')**'); for(const x of fails.slice(0,12)) lines.push('- '+x); }
const log={
  'Execution ID': String($execution.id),
  'Automation': 'Enrich Discogen Research',
  'Status': failedCount?'Succeeded with errors':'Succeeded',
  'Trigger': p.trigger||'form',
  'Errors': failedCount,
  'Run at': p.startedAt,
  'Target': (t.tableName||'Companies')+' ('+(t.tableId||'')+')',
  'View': t.viewName||p.view,
  'Records In': n(ps.inView),
  'Records Out': n(w.written),
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Tally': JSON.stringify({ execId:String($execution.id), pick:ps, results:Object.assign({},rs,{ submitErrors:rs.submitErrors.length, failedTasks:rs.failedTasks.length, timedOut:rs.timedOut.length }), written:n(w.written), writeErrors:n(w.writeErrors) }).slice(0,90000),
  'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id
};
if(p.clientRecId) log['Client']=[p.clientRecId];
return [{ json:log }];

// Build Refusal: the row a refused launch writes. A refusal is an expected outcome, not a crash:
// Launch Params, Resolve Table, Check Columns or Pick Rows named the reason instead of throwing, and
// this closes the row (already stamped Running with this Execution ID on a Hub launch) as Failed
// with the reason and the link. Nothing was submitted and nothing was paid for.
const p=$('Params').first().json||{};
const reasonOf=(name)=>{ try{ const j=$(name).first().json||{}; return String(j.refused||''); }catch(e){ return ''; } };
const reason=reasonOf('Pick Rows')||reasonOf('Check Columns')||reasonOf('Resolve Table')||String(p.refused||'')||'the launch was refused and no reason was recorded';
const show=(v)=>(v===''||v===null||v===undefined||v===0)?'(empty)':String(v);
const lines=[
  '**Refused before anything ran: '+reason+'**',
  '',
  '**Scope:** '+(p.clientRecId?('one client ('+p.clientRecId+')'):'no client resolved')+', launch '+(p._launchRecordId||'(event call, no launch row)'),
  '',
  '**The launch row as this machine read it**',
  '- **Client:** '+show(p.clientRecId),
  '- **Clayroots Base ID:** '+(p.base||'(empty, or the Clients row could not be read)'),
  '- **Table:** '+show(p.table)+' (only "Companies" is accepted)',
  '- **View:** '+show(p.view),
  '- **Prompt:** '+(p.prompt?String(p.prompt).replace(/\s+/g,' ').slice(0,200):'(empty)'),
  '- **Output Field:** '+show(p.outputField)+'; **Output Type:** '+show(p.outputType),
  '- **Web Search:** '+(p.webSearch?'on':'off')+'; **Evidence:** '+(p.evidence?'on':'off')+'; **Overwrite:** '+(p.overwrite?'on':'off'),
  '- **Max companies:** '+show(p.maxCompanies),
  '- **Tag:** '+show(p.tag),
  '',
  '**Failures (1)**',
  '- Launch guard: '+reason,
  '',
  'No DiscoGen task was submitted and nothing was written to the client base.',
  'Fix the named field on the launch row, clear Execution ID, and the Airtable door will fire it again.'
];
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const log={
  'Automation':'Enrich Discogen Research',
  'Status':'Failed',
  'Trigger': p.trigger||'form',
  'Errors': 1,
  'Run at': $now.toISO(),
  'Records In': 0,
  'Records Out': 0,
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Execution ID': String($execution.id)
};
if(p.view) log['View']=p.view;
if(p.clientRecId) log['Client']=[p.clientRecId];
return [{ json: log }];
